import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxChip,
  JxEmptyState,
  JxButton,
  JxPagination,
  JxProgressCircle,
  JxDivider,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'В норме', tone: 'success' },
  warning: { label: 'На пределе', tone: 'warning' },
  exceeded: { label: 'Превышен', tone: 'danger' },
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'warning', 'exceeded'];

const PROJECTS: Project[] = [
  { id: 'atlas', name: 'Атлас поиска', used: 4200, quota: 12000, status: 'active' },
  { id: 'beacon', name: 'Маяк аналитики', used: 10400, quota: 12000, status: 'warning' },
  { id: 'cinder', name: 'Сборка отчётов', used: 13100, quota: 12000, status: 'exceeded' },
  { id: 'delta', name: 'Дельта импорта', used: 2600, quota: 20000, status: 'active' },
  { id: 'echo', name: 'Эхо уведомлений', used: 7400, quota: 8000, status: 'warning' },
  { id: 'forge', name: 'Кузница шаблонов', used: 900, quota: 5000, status: 'active' },
  { id: 'grove', name: 'Роща документов', used: 6100, quota: 6000, status: 'exceeded' },
  { id: 'harbor', name: 'Гавань бэкапов', used: 3300, quota: 15000, status: 'active' },
  { id: 'ion', name: 'Ион транскрибации', used: 5600, quota: 6000, status: 'warning' },
  { id: 'jet', name: 'Джет выгрузок', used: 1200, quota: 9000, status: 'active' },
  { id: 'kite', name: 'Кайт метрик', used: 8800, quota: 10000, status: 'warning' },
  { id: 'lumen', name: 'Люмен дашбордов', used: 400, quota: 4000, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '8px' }}>
        {statuses.map((status) => (
          <JxChip key={status} active removable onRemove={() => removeStatus(status)}>
            {STATUS_META[status].label}
          </JxChip>
        ))}
        {statuses.length < ALL_STATUSES.length ? (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        ) : null}
      </div>

      <JxDivider label="Расход по проектам" />

      {rows.length === 0 ? (
        <JxEmptyState
          title="Проектов не нашлось"
          message="Ни один статус не выбран. Верните фильтры, чтобы увидеть расход по проектам."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {rows.map((project) => (
            <div
              key={project.id}
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr auto auto',
                alignItems: 'center',
                gap: '16px',
              }}
            >
              <span style={{ fontFamily: 'var(--jx-font-sans)', color: 'var(--jx-text)' }}>
                {project.name}
              </span>
              <JxProgressCircle value={project.used} max={project.quota} showValue />
              <JxBadge tone={STATUS_META[project.status].tone} dot>
                {STATUS_META[project.status].label}
              </JxBadge>
            </div>
          ))}

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </div>
      )}
    </section>
  );
}

